const heading = document.createElement("h1");
heading.id = "title";
heading.textContent = "Built with JavaScript";
document.body.append(heading);

console.log(document.querySelector("h1").textContent);
console.log(document.getElementById("title").tagName);
console.log(document.querySelectorAll("h1").length);
console.log(document.querySelector(".missing"));

const box = document.createElement("div");
box.innerHTML = "<p>One</p><p>Two</p>";     // parsed as markup
document.body.append(box);

console.log(box.children.length);
console.log(box.textContent);
console.log(box.querySelector("p").textContent);

box.textContent = "<b>not bold</b>";          // shown literally, no elements created
console.log(box.children.length);

const link = document.createElement("a");
link.setAttribute("href", "/tutorials/javascript");
link.textContent = "JavaScript tutorial";
link.classList.add("button", "primary");
link.dataset.track = "nav";
link.style.width = "40%";
document.body.append(link);

console.log(link.getAttribute("href"));
console.log(link.className);
console.log(link.classList.contains("primary"));
link.classList.toggle("primary");
console.log(link.className);
console.log(link.dataset.track);
console.log(link.style.width);

const fruits = ["apple", "banana", "cherry"];
const list = document.createElement("ul");

for (const fruit of fruits) {
  const item = document.createElement("li");
  item.textContent = fruit;
  list.append(item);
}
document.body.append(list);

console.log(list.querySelectorAll("li").length);
console.log(list.lastElementChild.textContent);

list.firstElementChild.remove();
console.log(list.firstElementChild.textContent);
console.log(list.outerHTML);
